import { RenderMode, ServerRoute } from '@angular/ssr';
import { deploymentConfig } from './deployment.config';

// Pages has no Node server. Catalog entries are generated by build-pages.mjs.
export function createPagesRoutes(adminAtRoot = false): ServerRoute[] {
  return [
    ...[
      '',
      'informacion-institucional',
      'privacidad',
      'terminos',
      'cancelaciones',
      'turismo-responsable',
      'libro-de-reclamaciones',
    ].map((path): ServerRoute =>
      path === '' && adminAtRoot
        ? { path, renderMode: RenderMode.Client }
        : { path, renderMode: RenderMode.Prerender },
    ),
    { path: '**', renderMode: RenderMode.Client },
  ];
}

export const serverRoutes: ServerRoute[] = createPagesRoutes(deploymentConfig.adminAtRoot === true);
